  "recovered_c": "uint64_t fn_19(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n    if (out_cap < len) {\n        return VERA_ERR;\n    }\n    if (len == 0) {\n        return len;\n    }\n    size_t i;\n    for (i = 0; i < len; i++) {\n        uint64_t processed = (arg >> (i % 8 * 8)) & 0xFF;\n        if ((i & 1) != 0 || DAT_00104010 != 0) {\n            processed = (processed ^ (i << 7)) * 'k' + DAT_00104008;\n        }\n        if (((i * i & 7) == 1) && DAT_00104008 == 0x3c71) {\n            break;\n        }\n        out[i] = (processed << (i % 8)) | (processed >> (8 - (i % 8))) ^ in[i] ^ (uint8_t)i;\n    }\n    return len;\n}"
